import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../assets";
import { ExternalTopbarDialog } from "../../../common/game-core";
import { OverlayScene } from "../../../common/scenes";

interface IProps {
  scene: Phaser.Scene;
}

interface IOneButtonDialogRequest {
  title?: string;
  text?: string;
  buttonText?: string;
  onClose?: () => void;
  isCloseOnOverlayClick?: boolean;
}

/**
 * Универсальный диалог с одной кнопкой.
 * Использует тот же механизм оверлея и top-bar, что и остальные shared-диалоги.
 */
export class OneButtonDialog {
  private dialog?: ExternalTopbarDialog;

  constructor(private readonly props: IProps) {}

  show(request: IOneButtonDialogRequest): void {
    /** Перед новым показом гарантированно удаляем предыдущий экземпляр. */
    this.destroyDialog();

    const overlayScene = OverlayScene.get(this.props.scene);
    const builder = new ViewElementBuilder(overlayScene);
    const align = new Align();

    const dialogText = builder.textDialog(request.text ?? "", {
      align: "center",
      fixedWidth: 700,
      wordWrap: {
        width: 700,
      },
    });

    const button = builder.buttonPrimary(request.buttonText ?? "Ok", () => {
      this.dialog?.close();
    }, {
      width: 300,
      height: 92,
      fontSizePx: 40,
    });

    align.anchor(dialogText).centerX(button).bottomTo(button, 42);

    const content = overlayScene.add.container(0, 0, [dialogText, button]);

    this.dialog = builder.dialogExternalTopTitle({
      title: request.title ?? "",
      content,
      width: 900,
      height: 380,
      isCloseOnOverlayClick: request.isCloseOnOverlayClick ?? true,
      onClose: () => {
        /** Освобождаем ссылку и пробрасываем завершение наружу. */
        this.dialog = undefined;
        request.onClose?.();
      },
    });

    this.dialog.show();
  }

  destroy(): void {
    this.destroyDialog();
  }

  private destroyDialog(): void {
    if (this.dialog == null) {
      return;
    }

    /** Явное destroy защищает от накопления оверлеев между повторными показами. */
    const activeDialog = this.dialog;
    this.dialog = undefined;
    activeDialog.destroy();
  }
}
