import {Align, arrayAlign} from "@kvisaz/phaser-sugar";
import {getLocalizedText, ViewElementBuilder} from "../../assets";
import {SpiderSuitsMode} from "../../common";
import {Scenes} from "../../common/game-core";
import {setSpiderSuitsMode} from "../../logic";
import {GameServiceProvider} from "../../services";
import {spiderModes, spiderModeTitleMap} from "./constants";

interface IProps {
    scene: Phaser.Scene;
}

export class SpiderStartView {
    constructor(private readonly props: IProps) {
        const {scene} = props;
        const builder = new ViewElementBuilder(scene);
        const align = new Align();

        const title = builder.textStartScreenTitle();
        align.anchorSceneScreen(scene).centerX(title).topIn(title, 24);


        const selectStyleButton = builder.buttonYellow(
            getLocalizedText('gameOver.congratulation'),
            () => {
                console.log('TODO make Select Style Screen');
            },
            {
                width: 438,
            }
        );
        align.anchorSceneScreen(scene).centerX(selectStyleButton).topIn(selectStyleButton, 397);


        const buttons = spiderModes.map((mode) => {
            return builder.buttonGreen(
                getLocalizedText(spiderModeTitleMap[mode]),
                () => this.startSpiderGame(mode),
            );
        });
        const buttonsLayout = arrayAlign.alignObject(arrayAlign.column(buttons, 20));
        align
            .anchorSceneScreen(scene)
            .center(buttonsLayout)
            .bottomIn(buttonsLayout, -80);

        builder.startHeroes();

        /** top right corner **/
        const buttonSettings = builder.buttonSettings(()=> {
           console.log('make onSettingsButtonClick event');
        });
        const settingsButtonLabel = builder.textSmallStart(getLocalizedText('settings.title'));
        align.anchorSceneScreen(scene).topIn(buttonSettings, 20).rightIn(buttonSettings, -20);
        align.anchor(buttonSettings).bottomTo(settingsButtonLabel, 5).rightIn(settingsButtonLabel);

        const buttonShop = builder.buttonShop(()=> {
            console.log('make onShopButtonClick event');
        });
        const shopButtonLabel = builder.textSmallStart(getLocalizedText('shop.title'));
        align.anchor(settingsButtonLabel).bottomTo(buttonShop, 20).rightIn(buttonShop);
        align.anchor(buttonShop).bottomTo(shopButtonLabel, 5).rightIn(shopButtonLabel);
    }

    private startSpiderGame(suitsMode: SpiderSuitsMode) {
        const {scene} = this.props;
        const gameService = GameServiceProvider.get();
        gameService.setPlayerData(setSpiderSuitsMode(suitsMode));
        scene.scene.start(Scenes.SpiderGame);
    }
}
